var e=Array.from(document.querySelectorAll(`.qr-btn`));e.forEach(t=>{t.addEventListener(`click`,()=>{let n=t.classList.toggle(`on`);t.setAttribute(`aria-expanded`,String(n)),e.forEach(e=>{e!==t&&(e.classList.remove(`on`),e.setAttribute(`aria-expanded`,`false`))})})}),document.addEventListener(`click`,t=>{t.target.closest(`.qr-btn`)||e.forEach(e=>{e.classList.remove(`on`),e.setAttribute(`aria-expanded`,`false`)})});